// Generated by @canonical/summon-component:react v0.43.0

import type { LinkComponentProps } from "@canonical/react-ds-global";
import { render, screen } from "@testing-library/react";
import type { ReactElement } from "react";
import { describe, expect, it } from "vitest";
import EntityCommand from "./EntityCommand.js";

/** A router link stand-in: an anchor that says it came through the router. */
const RouterLink = ({
  href,
  className,
  children,
}: LinkComponentProps): ReactElement => (
  <a className={className} data-router="" href={href}>
    {children}
  </a>
);

/** Render one result in the list it belongs to and return the result. */
function renderCommand(command: ReactElement): HTMLElement {
  render(<ul>{command}</ul>);
  return screen.getByRole("listitem");
}

describe("EntityCommand", () => {
  describe("title", () => {
    it("renders the title alone, as inert text", () => {
      const row = renderCommand(<EntityCommand title="Danger" />);
      expect(screen.getByText("Danger").className).toBe("title");
      expect(row.querySelector(".context")).toBeNull();
      expect(row.querySelector(".vital")).toBeNull();
      expect(screen.queryByRole("link")).toBeNull();
    });
  });

  describe("kind and location", () => {
    it("reads kind and location as the catalog's one sentence", () => {
      const row = renderCommand(
        <EntityCommand kind="Modifier" location="DS:Global" title="Danger" />,
      );
      const context = row.querySelector(".context");
      expect(context?.textContent).toBe("Modifier in DS:Global");
      expect(
        [...(context?.children ?? [])].map((child) => child.className),
      ).toEqual(["kind", "location"]);
    });

    it("renders a lone kind alone", () => {
      const row = renderCommand(<EntityCommand kind="Class" title="Layout" />);
      expect(row.querySelector(".context")?.innerHTML).toBe(
        '<span class="kind">Class</span>',
      );
    });

    it("renders a lone location alone", () => {
      const row = renderCommand(
        <EntityCommand location="design-system" title="Layout" />,
      );
      expect(row.querySelector(".context")?.innerHTML).toBe(
        '<span class="location">design-system</span>',
      );
    });
  });

  describe("vital", () => {
    it("ends the row with the vital, after the identity", () => {
      const row = renderCommand(<EntityCommand title="Danger" vital="v1.11" />);
      expect(row.lastElementChild?.className).toBe("vital");
      expect(row.lastElementChild?.textContent).toBe("v1.11");
    });
  });

  describe("href and LinkComponent", () => {
    it("links the title to the home through an intrinsic anchor by default", () => {
      renderCommand(<EntityCommand href="#danger" title="Danger" />);
      const link = screen.getByRole("link", { name: "Danger" });
      expect(link.getAttribute("href")).toBe("#danger");
      expect(link.className).toBe("title");
    });

    it("links only the title, through the LinkComponent it is given", () => {
      renderCommand(
        <EntityCommand
          href="#danger"
          kind="Modifier"
          LinkComponent={RouterLink}
          location="DS:Global"
          title="Danger"
          vital="v1.11"
        />,
      );
      const links = screen.getAllByRole("link");
      expect(links).toHaveLength(1);
      expect(links.at(0)?.hasAttribute("data-router")).toBe(true);
    });
  });

  describe("native props", () => {
    it("forwards native props to the root and merges className after its own", () => {
      const row = renderCommand(
        <EntityCommand
          aria-selected="true"
          className="result"
          title="Danger"
        />,
      );
      expect(row.className).toBe("ds entity-command result");
      expect(row.getAttribute("aria-selected")).toBe("true");
    });
  });
});
